-- Creature and gameobject data from the earlier Keira3 based generator, not regenerated yet.
-- The spell editor data lives in Spell*.lua, generated by HoT/Editor/DataGen/gen.py.
GameEditorData = GameEditorData or {}

-- Groups[table] = ordered UI sections. Every column of the table appears exactly once.
--   effect = n marks a per-effect section, dataByType names the column that picks GameObjectData
GameEditorData.Groups = GameEditorData.Groups or {}

GameEditorData.Groups.creature = {
    {title = "Base", columns = {"guid", "id", "modelid", "equipment_id"}},
    {title = "Position", columns = {"map", "zoneId", "areaId", "position_x", "position_y", "position_z", "orientation"}},
    {title = "Spawn", columns = {"spawnMask", "phaseMask", "spawntimesecs", "curhealth", "curmana"}},
    {title = "Movement", columns = {"MovementType", "wander_distance", "currentwaypoint"}},
    {title = "Flags", columns = {"npcflag", "unit_flags", "dynamicflags"}},
    {title = "Scripts", columns = {"ScriptName", "StringId"}},
    {title = "Misc", columns = {"VerifiedBuild"}},
}

